package com.nvv.mediadata.view.coreimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material3.Surfaceimport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.unit.dp@Composablefun ListItem(	content: @Composable () -> Unit,) {	Surface(		modifier = Modifier			.fillMaxWidth()			.padding(top = 16.dp),		shape = RoundedCornerShape(16.dp),		color = Color(0xFF2B272C)	) {		Column {			content()		}	}}